const aiResponse = items[0].json.output || items[0].json.text || items[0].json.response;

try {
    // Parse the JSON response
    let roadmapResult;
    if (typeof aiResponse === 'string') {
        const cleanResponse = aiResponse.replace(/```json\n?|\n?```/g, '').trim();
        roadmapResult = JSON.parse(cleanResponse);
    } else {
        roadmapResult = aiResponse;
    }

    // Validate required fields and provide defaults
    const requiredFields = {
        'mvp_features': [],
        'mvp_timeline': '3 months',
        'phase2_features': [],
        'phase2_timeline': '6 months',
        'phase3_features': [],
        'phase3_timeline': '12 months',
        'dependencies': [],
        'team_requirements': {},
        'mvp_success_metrics': [],
        'critical_path': []
    };

    // Ensure all required fields exist with defaults
    for (const [field, defaultValue] of Object.entries(requiredFields)) {
        if (!roadmapResult[field]) {
            roadmapResult[field] = defaultValue;
        }
    }

    // Ensure arrays are properly formatted
    const arrayFields = ['mvp_features', 'phase2_features', 'phase3_features', 'dependencies',
                         'critical_path', 'parallel_development', 'mvp_success_metrics',
                         'phase2_success_metrics', 'phase3_success_metrics', 'go_to_market_timeline'];

    for (const field of arrayFields) {
        if (roadmapResult[field] && !Array.isArray(roadmapResult[field])) {
            roadmapResult[field] = [];
        }
    }

    // Ensure nested objects exist
    if (!roadmapResult.team_requirements || typeof roadmapResult.team_requirements !== 'object') {
        roadmapResult.team_requirements = {
            mvp_phase: ['Product Manager', 'Frontend Developer', 'Backend Developer'],
            scaling_phase: ['UI/UX Designer', 'DevOps Engineer', 'QA Engineer']
        };
    }

    if (!roadmapResult.resource_allocation || typeof roadmapResult.resource_allocation !== 'object') {
        roadmapResult.resource_allocation = {
            development_effort: '60% MVP, 30% Phase 2, 10% Phase 3',
            design_effort: '40% MVP, 35% Phase 2, 25% Phase 3',
            testing_effort: '50% MVP, 30% Phase 2, 20% Phase 3'
        };
    }

    // Create a summary for easy reference
    roadmapResult.roadmap_summary = `MVP (${roadmapResult.mvp_timeline}): ${roadmapResult.mvp_features.length} features`;

    return [{
        json: {
            ...items[0].json,
            roadmapResult: roadmapResult
        }
    }];
} catch (error) {
    console.error('Error parsing roadmap response:', error);
    throw new Error(`Failed to parse roadmap agent response: ${error.message}`);
}
